def get_help_hub_page(category: str, lang: str = 'ru') -> str:
    """Возвращает форматированный текст раздела справки для указанного языка."""
    pages = HELP_HUB_PAGES_RU
    if lang == 'en':
        pages = HELP_HUB_PAGES_EN
    elif lang == 'jp':
        pages = HELP_HUB_PAGES_JP

    cat_clean = (category or "main").strip().lower()
    alias_map = {
        "heists": "heist",
        "налет": "heist",
        "налёт": "heist",
        "ограбление": "heist",
        "loans": "loan",
        "займ": "loan",
        "заем": "loan",
        "долг": "loan",
        "даркнет": "darknet",
        "криминал": "crime",
        "syndicate": "crime",
        "laundering": "crime",
        "стирка": "crime",
        "отмыв": "crime",
        "cases": "cases",
        "lootbox": "lootbox",
        "dice_duel": "dice_duel",
        "duel": "duel",
        "work": "work",
        "shop": "shop",
        "casino": "casino",
    }
    target_cat = alias_map.get(cat_clean, cat_clean)
    return pages.get(target_cat, pages.get(cat_clean, pages.get("main", "⚡ Справка ТГАЧ")))

